   168|async function readJsonPayload(response: Response): Promise<Record<string, unknown>> {
   169|  const text = await response.text();
   170|  if (!text) return {};
   171|  try {
   172|    const parsed = JSON.parse(text) as unknown;
   173|    return isRecord(parsed) ? parsed : { value: parsed };
   174|  } catch {
   175|    return { raw: text.slice(0, 500) };
   176|  }
