   179|async function fetchOwnerApprovedJson<T extends Record<string, unknown>>(
   180|  suffix: string,
   181|  init: RequestInit,
   182|): Promise<T & { httpStatus: number }> {
   183|  const accessToken = await getRealSupabaseOwnerBearer();
   184|  const urls = buildSeniorDeveloperUrls(suffix);
   185|  if (urls.length === 0) {
   186|    throw new Error('Senior-developer backend URL is not configured.');
   187|  }
   188|
   189|  let lastError: Error | null = null;
   190|  for (const url of urls) {
   191|    try {
   192|      console.log('[SeniorDeveloperApprovalService] Sending owner-approved request', { bearerHeaderPresent: true, url: suffix });
   193|      const response = await fetch(url, {
   194|        ...init,
   195|        headers: {
   196|          Accept: 'application/json',
   197|          'Content-Type': 'application/json',
   198|          Authorization: `Bearer ${accessToken}`,
   199|          ...(init.headers ?? {}),
   200|        },
   201|      });
   202|      const payload = await readJsonPayload(response);
   203|      const typedPayload = { ...payload, httpStatus: response.status } as T & { httpStatus: number };
   204|      if (!response.ok) {
   205|        const message = typeof payload.exactBlocker === 'string'
   206|          ? payload.exactBlocker
   207|          : typeof payload.error === 'string'
