   210|        const error = new Error(message);
   211|        (error as Error & { payload?: unknown }).payload = typedPayload;
   212|        throw error;
   213|      }
   214|      return typedPayload;
   215|    } catch (error) {
   216|      lastError = error instanceof Error ? error : new Error(String(error));
   217|    }
   218|  }
   219|  throw lastError ?? new Error('Senior-developer backend is not reachable.');
